function useToggle(key: string, defaultValue = false) {
  const [value, setValue] = useState(defaultValue);
  const toggle = useCallback(() => setValue(v => !v), []);
  return [value, toggle] as const;
}

function useLocalStorage<T>(key: string, initialValue: T) {
  const [value, setValue] = useState<T>(() => {
    const stored = localStorage.getItem(key);
    return stored ? JSON.parse(stored) : initialValue;
  });

  useEffect(() => {
    localStorage.setItem(key, JSON.stringify(value));
  }, [key, value]);

  return [value, setValue] as const;
}

// Composed hook
function usePersistentToggle(key: string) {
  const [value, setValue] = useLocalStorage(key, false);
  const toggle = useCallback(() => setValue(v => !v), [setValue]);
  return [value, toggle] as const;
}

function useLoading(initial = false) {
  return useState(initial)[0];
}

function useError<T = Error>() {
  return useState<T | null>(null);
}

function useAsync<T>(asyncFn: () => Promise<T>, deps: any[]) {
  const dataState = useState<T | null>(null);
  const errorState = useError<T>();
  const loading = useLoading(true);

  useEffect(() => {
    let cancelled = false;

    asyncFn()
      .then(result => {
        if (!cancelled) dataState[1](result);
      })
      .catch(err => {
        if (!cancelled) errorState[1](err);
      })
      .finally(() => {
        if (!cancelled) {
          loading(false); // This won't work directly, see note
        }
      });

    return () => { cancelled = true; };
  }, deps);

  return { data: dataState[0], error: errorState[0], loading };
}
